import java.util.List;

import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;

/**
 * Streaming (Welford) accumulation of the co-moment of two numeric series, behind {@code agg:corr},
 * {@code agg:covarPop} and {@code agg:covarSamp}. Numerically stable and single pass.
 */
public class CoMomentCollector extends ExtensionCollector {

	public enum Statistic {
		CORRELATION,
		POPULATION_COVARIANCE,
		SAMPLE_COVARIANCE
	}

	private final Statistic statistic;
	private long n;
	private double meanX;
	private double meanY;
	private double m2x;
	private double m2y;
	private double coMoment;

	public CoMomentCollector(Statistic statistic) {
		this.statistic = statistic;
	}

	@Override
	public void addTuple(List<Value> tuple) {
		double x = NumericValues.asDouble(tuple.get(0));
		double y = NumericValues.asDouble(tuple.get(1));
		n++;
		double dx = x - meanX;
		meanX += dx / n;
		double dy = y - meanY;
		meanY += dy / n;
		double dy2 = y - meanY;
		coMoment += dx * dy2;
		m2x += dx * (x - meanX);
		m2y += dy * dy2;
	}

	@Override
	protected Value computeValue() {
		double result;
		switch (statistic) {
		case POPULATION_COVARIANCE:
			if (n == 0) {
				return null;
			}
			result = coMoment / n;
			break;
		case SAMPLE_COVARIANCE:
			if (n < 2) {
				return null;
			}
			result = coMoment / (n - 1);
			break;
		default:
			if (n < 2 || m2x == 0 || m2y == 0) {
				return null;
			}
			result = coMoment / Math.sqrt(m2x * m2y);
		}
		return SimpleValueFactory.getInstance().createLiteral(result);
	}
}
